source('R/stile.R')
d<-leggi('fossili_simulati.csv');x<-d$diametro_tot_um;y<-d$diametro_int_um;fit<-lm(y~x)
salva('M07','F01',ggplot(d,aes(diametro_tot_um,diametro_int_um))+geom_point(aes(colour=morfotipo),size=1.6,alpha=.7)+geom_smooth(method='lm',formula=y~x,se=FALSE,colour=geo[3],linewidth=1)+scale_colour_manual(values=geo[1:2])+labs(x='Diametro totale (µm)',y='Diametro interno (µm)'))
set.seed(702);u<-seq(-2,2,length.out=80);z<-data.frame(x=u,y=u^2+rnorm(80,0,.2))
salva('M07','F02',ggplot(z,aes(x,y))+geom_point(colour=geo[1],size=1.8)+labs(x='x',y='y'))
new<-data.frame(x=seq(min(x),max(x),length.out=200));ci<-predict(fit,new,interval='confidence');pi<-predict(fit,new,interval='prediction');z<-data.frame(x=new$x,fit=ci[,1],cl=ci[,2],cu=ci[,3],pl=pi[,2],pu=pi[,3])
salva('M07','F03',ggplot(z,aes(x,fit))+geom_ribbon(aes(ymin=pl,ymax=pu),fill=geo[2],alpha=.15)+geom_ribbon(aes(ymin=cl,ymax=cu),fill=geo[1],alpha=.5)+geom_line(colour=geo[1],linewidth=1)+labs(x='Diametro totale (µm)',y='Diametro interno (µm)'))
z<-data.frame(fit=fitted(fit),res=residuals(fit),std=rstandard(fit),leva=hatvalues(fit),cook=cooks.distance(fit))
salva('M07','F04',ggplot(z,aes(fit,res))+geom_point(colour=geo[1],size=1.6)+geom_hline(yintercept=0,linetype=2,colour=geo[2])+geom_smooth(method='loess',formula=y~x,se=FALSE,colour=geo[3],linewidth=.8)+labs(x='Valore stimato (µm)',y='Residuo (µm)'))
salva('M07','F05',ggplot(z,aes(sample=std))+stat_qq(colour=geo[1],size=1.5)+stat_qq_line(colour=geo[2],linewidth=.8)+labs(x='Quantile normale',y='Residuo standardizzato'))
salva('M07','F06',ggplot(z,aes(leva,std,size=cook))+geom_point(colour=geo[1],alpha=.7)+scale_size_area(max_size=7,breaks=c(.01,.03,.06),labels=c('D = 0,01','D = 0,03','D = 0,06'))+guides(size=guide_legend(nrow=1))+labs(x='Leva',y='Residuo standardizzato'))
salva('M07','F07',ggplot(d,aes(diametro_tot_um,diametro_int_um,colour=morfotipo))+geom_point(alpha=.4,size=1.3)+geom_smooth(method='lm',formula=y~x,se=FALSE,linewidth=1)+scale_colour_manual(values=geo[1:2])+labs(x='Diametro totale (µm)',y='Diametro interno (µm)'))
d$spiky<-as.integer(d$morfotipo=='Spiky');logit<-glm(spiky~diametro_tot_um,d,family=binomial());z<-data.frame(diametro_tot_um=seq(min(x),max(x),length.out=200));z$p<-predict(logit,z,type='response')
salva('M07','F08',ggplot(d,aes(diametro_tot_um,spiky))+geom_point(position=position_jitter(width=0,height=.025,seed=708),alpha=.35,colour=geo[2],size=1.1)+geom_line(data=z,aes(y=p),colour=geo[1],linewidth=1.2)+scale_y_continuous(breaks=c(0,.5,1))+labs(x='Diametro totale (µm)',y='Probabilità Spiky'))
set.seed(709);idx<-unlist(lapply(split(seq_len(nrow(d)),d$morfotipo),function(i)sample(i,60)))
tr<-d[idx,];te<-d[-idx,];a<-lm(diametro_int_um~diametro_tot_um,tr);b<-lm(diametro_int_um~poly(diametro_tot_um,2),tr)
pr<-list(Media=rep(mean(tr$diametro_int_um),nrow(te)),Retta=predict(a,te),Quadratica=predict(b,te));z<-data.frame(Modello=factor(names(pr),levels=names(pr)),RMSE=vapply(pr,function(v)sqrt(mean((te$diametro_int_um-v)^2)),0.0))
salva('M07','F09',ggplot(z,aes(Modello,RMSE,fill=Modello))+geom_col(width=.6)+scale_fill_manual(values=geo[1:3],guide='none')+labs(x=NULL,y='RMSE sul test (µm)'))
dir.create('risultati/M07',recursive=TRUE,showWarnings=FALSE)
write.csv(data.frame(id=te$id,osservato=te$diametro_int_um,as.data.frame(pr)),'risultati/M07/previsioni_test.csv',row.names=FALSE)
X<-model.matrix(fit);beta<-qr.solve(X,y);e<-y-X%*%beta
verifica('coefficienti QR e lm',max(abs(beta-coef(fit)))<1e-12)
verifica('equazioni normali',max(abs(crossprod(X,e)))<1e-10)
verifica('pendenza correlazione',abs(coef(fit)[2]-cor(x,y)*sd(y)/sd(x))<1e-12)
x0<-c(1,6);h0<-as.numeric(t(x0)%*%solve(crossprod(X),x0));s<-summary(fit)$sigma;delta<-qt(.975,nrow(X)-ncol(X))*s*sqrt(h0)
manuale<-sum(x0*coef(fit))+c(-delta,delta)
verifica('intervallo media',max(abs(manuale-predict(fit,data.frame(x=6),interval='confidence')[1,2:3]))<1e-12)
verifica('predizione più ampia',all(pi[,3]-pi[,2]>ci[,3]-ci[,2]))
verifica('identità geometrica',max(abs(d$diametro_tot_um-d$diametro_int_um-2*d$spessore_um))<3e-8)
verifica('separazione dei casi',length(intersect(tr$id,te$id))==0 && nrow(tr)==120 && nrow(te)==40)
verifica('probabilità logistiche',all(fitted(logit)>0 & fitted(logit)<1))
